// ══════════════════════════════════════════════════════════════════
// LDI LIVE SIMULATOR — Ornstein-Uhlenbeck mean-reverting sensor model
// สร้างข้อมูลที่ "เคลื่อนไหวต่อเนื่อง" เหมือนเซ็นเซอร์จริง ไม่ใช่สุ่มอิสระ
// ══════════════════════════════════════════════════════════════════
const P = {"LDI-01": {"process": "DF INNER", "share": 0.166, "temp_mu": 21.19, "temp_sd": 0.13, "rh_mu": 56.23, "rh_sd": 1.63, "dosage": 69.591, "scan": 220.0, "vac": -16.08, "thick_mu": 0.529, "thick_sd": 0.365, "pe_setting": 1.79769313486232, "je_setting": 30.0, "scale_mode": "FixedScale", "factory": "2", "pe": null, "je": [[7.9, 2.22], [4.41, 2.29], [10.87, 3.01], null], "layers": ["mk-inner-a", "mk-inner-b", "mk-inner-c", "mk-inner-d"]}, "LDI-02": {"process": "DF INNER", "share": 0.166, "temp_mu": 26.49, "temp_sd": 0.09, "rh_mu": 52.52, "rh_sd": 1.58, "dosage": 69.591, "scan": 220.0, "vac": -17.21, "thick_mu": 0.528, "thick_sd": 0.365, "pe_setting": 1.79769313486232, "je_setting": 30.0, "scale_mode": "FixedScale", "factory": "2", "pe": null, "je": [[2.23, 0.97], [1.63, 1.39], [2.25, 1.26], null], "layers": ["mk-inner-a", "mk-inner-b", "mk-inner-c", "mk-inner-d"]}, "LDI-03": {"process": "DF INNER", "share": 0.109, "temp_mu": 20.92, "temp_sd": 0.08, "rh_mu": 56.7, "rh_sd": 0.36, "dosage": 75.708, "scan": 260.0, "vac": -19.15, "thick_mu": 0.264, "thick_sd": 0.0, "pe_setting": 30.0, "je_setting": 30.0, "scale_mode": "FixedScale", "factory": "3", "pe": null, "je": [[2.27, 0.28], [1.79, 0.31], [1.13, 0.36], null], "layers": ["mk-inner-a", "mk-inner-b", "mk-inner-c", "mk-inner-d"]}, "LDI-04": {"process": "DF INNER", "share": 0.109, "temp_mu": 22.58, "temp_sd": 0.06, "rh_mu": 52.69, "rh_sd": 0.27, "dosage": 72.904, "scan": 270.0, "vac": -17.86, "thick_mu": 0.264, "thick_sd": 0.0, "pe_setting": 1.79769313486232, "je_setting": 40.0, "scale_mode": "FixedScale", "factory": "3", "pe": null, "je": [[5.94, 1.49], [17.46, 1.74], [11.94, 1.93], null], "layers": ["mk-inner-a", "mk-inner-b", "mk-inner-c", "mk-inner-d"]}, "LDI-05": {"process": "DF OUTER", "share": 0.172, "temp_mu": 22.39, "temp_sd": 0.14, "rh_mu": 50.55, "rh_sd": 0.5, "dosage": 15.0, "scan": 435.0, "vac": 0.0, "thick_mu": 1.141, "thick_sd": 0.325, "pe_setting": 75.0, "je_setting": 50.0, "scale_mode": "Fixed", "factory": "2", "pe": [[-6.22, 12.26], [-5.35, 18.69], [-14.76, 21.32], [1.23, 21.44], [-3.21, 18.67], [-5.23, 10.92]], "je": [[12.63, 7.15], [10.72, 6.3], [10.27, 5.95], [12.01, 6.65]], "layers": ["mk-outer-a", "mk-outer-b"]}, "LDI-06": {"process": "DF OUTER", "share": 0.171, "temp_mu": 21.88, "temp_sd": 0.1, "rh_mu": 52.56, "rh_sd": 0.45, "dosage": 15.0, "scan": 435.0, "vac": 0.0, "thick_mu": 1.139, "thick_sd": 0.325, "pe_setting": 75.0, "je_setting": 50.0, "scale_mode": "Fixed", "factory": "2", "pe": [[3.56, 12.01], [9.55, 15.94], [2.93, 18.46], [15.06, 18.61], [7.23, 16.86], [3.51, 10.32]], "je": [[9.43, 5.92], [11.35, 7.28], [11.1, 7.13], [9.26, 5.69]], "layers": ["mk-outer-a", "mk-outer-b"]}, "LDI-07": {"process": "SM", "share": 0.037, "temp_mu": 22.33, "temp_sd": 0.08, "rh_mu": 55.83, "rh_sd": 0.44, "dosage": 568.0, "scan": 104.7, "vac": 0.0, "thick_mu": 0.986, "thick_sd": 0.335, "pe_setting": 50.0, "je_setting": 50.0, "scale_mode": "Auto", "factory": "2", "pe": [[0.37, 2.72], [-13.87, 6.56], [-5.44, 5.24], [5.91, 5.53], [14.22, 6.78], [-0.9, 2.66]], "je": [[9.22, 5.03], [9.9, 5.06], [5.92, 2.63], [5.37, 2.49]], "layers": ["mk-solder-a", "mk-solder-b", "mk-comp-a"]}, "LDI-08": {"process": "SM", "share": 0.037, "temp_mu": 22.49, "temp_sd": 0.09, "rh_mu": 53.18, "rh_sd": 0.37, "dosage": 595.3, "scan": 101.8, "vac": 0.0, "thick_mu": 0.986, "thick_sd": 0.336, "pe_setting": 50.0, "je_setting": 50.0, "scale_mode": "Auto", "factory": "2", "pe": [[-0.1, 5.59], [-9.76, 9.65], [-3.48, 3.27], [3.16, 3.16], [9.52, 9.45], [0.46, 5.82]], "je": [[7.53, 5.73], [6.59, 3.75], [4.94, 2.79], [5.66, 5.31]], "layers": ["mk-solder-a", "mk-solder-b", "mk-comp-a"]}, "LDI-09": {"process": "SM", "share": 0.017, "temp_mu": 21.98, "temp_sd": 0.04, "rh_mu": 55.63, "rh_sd": 0.07, "dosage": 500.0, "scan": 115.86, "vac": 0.0, "thick_mu": 1.174, "thick_sd": 0.05, "pe_setting": 25.0, "je_setting": 25.0, "scale_mode": "Auto", "factory": "3", "pe": [[1.37, 2.32], [-5.73, 4.63], [1.06, 3.69], [-1.07, 3.7], [5.73, 4.64], [-1.36, 2.38]], "je": [[3.2, 2.4], [3.7, 2.15], [4.08, 2.35], [3.72, 2.48]], "layers": ["mk-solder-a", "mk-solder-b", "mk-comp-a"]}, "LDI-10": {"process": "SM", "share": 0.017, "temp_mu": 22.31, "temp_sd": 0.04, "rh_mu": 55.03, "rh_sd": 0.09, "dosage": 500.0, "scan": 115.86, "vac": 0.0, "thick_mu": 1.174, "thick_sd": 0.05, "pe_setting": 25.0, "je_setting": 25.0, "scale_mode": "Auto", "factory": "3", "pe": [[0.69, 1.55], [-4.98, 2.47], [1.03, 2.72], [-1.0, 2.72], [4.96, 2.46], [-0.74, 1.59]], "je": [[2.35, 1.36], [2.68, 1.53], [3.48, 1.3], [3.12, 1.33]], "layers": ["mk-solder-a", "mk-solder-b", "mk-comp-a"]}};
const SENTINEL = 1.79769313486232;

// ── OU process: x[t+1] = x + theta*(mu - x)*dt + sigma*sqrt(dt)*N(0,1) ──
// theta = ความเร็วที่ดึงกลับสู่ค่าเป้าหมาย (0.15 = ค่อยๆ กลับ ~7 ticks)
// ผลลัพธ์: ค่าไหลลื่นต่อเนื่อง มี autocorrelation จริง ไม่กระโดดทุก tick
const THETA = 0.15, DT = 1.0;
function gauss() {
    let u = 0, v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
function ou(prev, mu, sigma) {
    if (prev === undefined || prev === null) return mu + sigma * gauss();
    return prev + THETA * (mu - prev) * DT + sigma * Math.sqrt(DT) * gauss();
}
function r(x, n) { const p = Math.pow(10, n); return Math.round(x * p) / p; }

const st = flow.get('sim_state') || {};
const now = Date.now();
const batch = [];

for (const id of Object.keys(P)) {
    const p = P[id];
    let s = st[id];
    if (!s) {
        s = { temp: p.temp_mu, rh: p.rh_mu, board: 1,
              total: 120 + Math.floor(Math.random() * 120),
              mo: 'MO-' + String(Math.floor(Math.random() * 90000) + 10000),
              fpn: 'PN-' + String.fromCharCode(65 + Math.floor(Math.random() * 24)) +
                   String(Math.floor(Math.random() * 900) + 100),
              layer: p.layers[Math.floor(Math.random() * p.layers.length)],
              resist: ["RESIST-A18", "RESIST-A22", "RESIST-B15", "RESIST-B30", "RESIST-C12"][Math.floor(Math.random()*5)],
              acc: 0 };
    }
    // ── อัตราการผลิตต่อเครื่องตามสัดส่วนจริง (share) ──
    // fleet รวม ~0.5 แถว/วินาที → เครื่อง share 0.17 ได้ ~0.085 แถว/วิ
    s.acc += p.share * 2.0;              // tick ทุก 2 วิ
    if (s.acc < 1) { st[id] = s; continue; }
    s.acc -= 1;

    // ── OU drift ของสภาพแวดล้อม ──
    s.temp = ou(s.temp, p.temp_mu, p.temp_sd);
    s.rh   = ou(s.rh,   p.rh_mu,   p.rh_sd);

    // ── เหตุการณ์หายาก (อัตราตรงกับของจริง 0.02%) ──
    const dropout = Math.random() < 0.0002;
    const stopped = Math.random() < 0.0002;

    // ── board cycle: นับขึ้นจนครบแล้วเริ่ม job ใหม่ ──
    s.board += 1;
    if (s.board > s.total) {
        s.board = 1;
        s.total = 120 + Math.floor(Math.random() * 120);
        s.mo = 'MO-' + String(Math.floor(Math.random() * 90000) + 10000);
        s.fpn = 'PN-' + String.fromCharCode(65 + Math.floor(Math.random() * 24)) +
                String(Math.floor(Math.random() * 900) + 100);
        s.layer = p.layers[Math.floor(Math.random() * p.layers.length)];
    }

    const rec = {
        time: new Date(now).toISOString(),
        eqp_id: id, factory: p.factory, process: p.process,
        mo: s.mo, fpn: s.fpn, layer_name: s.layer,
        resist_dosage: p.dosage,      // ← ค่าคงที่ต่อเครื่อง (sd=0 ในข้อมูลจริง)
        scan_speed: p.scan,           // ← ค่าคงที่ต่อเครื่อง
        air_vacuum: p.vac,            // ← DF OUTER/SM = 0 พอดี (ทดสอบบั๊ก zero-coercion)
        scale_x: dropout ? 0 : r(1.000282 + gauss() * 0.000099, 6),
        scale_y: dropout ? 0 : r(1.000280 + gauss() * 0.000099, 6),
        temperature: dropout ? 0 : r(s.temp, 1),
        humidity:    dropout ? 0 : r(s.rh, 1),
        thickness: r(Math.max(0.26, p.thick_mu + gauss() * p.thick_sd), 3),
        board_no: s.board, total_board: s.total,
        total_time: r(Math.max(5, 7 + Math.abs(gauss()) * (p.process === 'SM' ? 18 : 3)), 3),
        filmno: null, board_id: null,
        resist: s.resist,             // ← สตริง ไม่ใช่ตัวเลข (ทดสอบบั๊ก type)
        state: !stopped,
        scale_mode: p.scale_mode,
        pe_setting: p.pe_setting, je_setting: p.je_setting
    };

    // ── PE: วัดเฉพาะเครื่องที่มีสเปกจริง + จับคู่สมมาตร 1↔6, 2↔5, 3↔4 ──
    if (p.pe) {
        const base = [gauss(), gauss(), gauss()];   // สุ่ม 3 ค่า
        const pairs = [[0, 5], [1, 4], [2, 3]];     // แล้วสะท้อนเป็น 6 จุด
        const out = [0, 0, 0, 0, 0, 0];
        for (let k = 0; k < 3; k++) {
            const [a, b] = pairs[k];
            const za = base[k], zb = -base[k] + gauss() * 0.15;   // สะท้อน + noise เล็กน้อย
            out[a] = p.pe[a][0] + za * p.pe[a][1];
            out[b] = p.pe[b][0] + zb * p.pe[b][1];
        }
        for (let k = 0; k < 6; k++) rec['pe_' + (k + 1)] = r(out[k], 3);
    } else {
        for (let k = 1; k <= 6; k++) rec['pe_' + k] = null;   // DF INNER ไม่วัด PE
    }
    // ── JE: je_4 เป็น NULL คู่กับ PE เสมอ ──
    for (let k = 0; k < 4; k++) {
        const j = p.je[k];
        rec['je_' + (k + 1)] = j ? r(Math.max(0, j[0] + Math.abs(gauss()) * j[1]), 1) : null;
    }
    rec.log_id = 'SIM-' + id.slice(-2) + '-' + now + '-' + s.board;

    batch.push(rec);
    st[id] = s;
}

flow.set('sim_state', st);
if (batch.length === 0) return null;

msg.payload = batch;
msg.headers = { 'Content-Type': 'application/json', 'x-api-key': env.get('INGEST_API_KEY') };
node.status({ fill: 'green', shape: 'dot', text: batch.length + ' rows @ ' + new Date().toLocaleTimeString() });
return msg;

if (msg.statusCode !== 200) {
    node.error('Simulator ingest failed: HTTP ' + msg.statusCode +
        ' ' + JSON.stringify(msg.payload), msg);
    node.status({fill:'red',shape:'ring',text:'HTTP '+msg.statusCode});
    return null;
}
node.status({fill:'blue',shape:'dot',text:'ok '+(msg.payload && msg.payload.count)});
return null;
